SELECT
  count(p.id) AS products_matched_by_id,
  count(*) FILTER (WHERE v.new_price IS NOT NULL AND p.selling_price = v.new_price) AS prices_already_new,
  count(*) FILTER (WHERE v.new_price IS NOT NULL AND p.selling_price = v.old_price) AS prices_still_old,
  count(*) FILTER (WHERE p.category = v.new_cat)                    AS categories_already_new,
  count(*) FILTER (WHERE p.category IS NOT DISTINCT FROM v.old_cat AND p.category IS DISTINCT FROM v.new_cat) AS categories_still_old,
  count(*) FILTER (WHERE v.new_ta IS NOT NULL AND p.tamil_name = v.new_ta) AS tamil_already_new,
  (SELECT string_agg(p2.name || ' = ₹' || p2.selling_price || ' / ' || coalesce(p2.category,'-'), ' | ')
     FROM products p2 WHERE p2.id IN ('6f28cafb-c60c-4cc0-b877-83fff30c21bf','87c1e16d-29fe-45a6-9392-cc46cdc2472d')) AS sample
FROM v LEFT JOIN products p ON p.id = v.id;
